from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class CellMappingInfoV1(SchemaObject):
    nr_cell_id = SchemaField(name='nr_cell_id', not_null=True)
    sub_cells = SchemaField(name='sub_cells', many=True)

    def __init__(self, nr_cell_id, sub_cells):
        self.nr_cell_id = nr_cell_id
        self.sub_cells = sub_cells
        super(CellMappingInfoV1, self).__init__()
